void abort(void);
void exit(int);

int i, a[99];

void f(int one) {
  if (one != 1)
    abort();
}

void g() { f(a[i & 0x3f]); }

int main() {
  a[0] = 1;
  i    = 0x40;
  g();
  exit(0);
}


